\begin{array}{l}
\text { Magnetic field, } \mathrm{B}_{\text {centre }}=\frac{\mu_{0}}{4 \pi} \cdot \frac{2 \pi i}{r} \\
=\frac{\mu_{0}}{4 \pi} \cdot \frac{2 \pi \times 100 e}{r} \\
